/**
 * Input chips (spec/02 §2.9): one chip per value of [values], the word (label at 400, text) in a drawn 36 dp frame
 * (1 dp borderStrong, radius 8) and a 48 dp remove button (close 16 dp, „<Wert> entfernen“) that calls [onRemove] with
 * the index. Chips wrap 8 dp apart; [groupLabel] names the group. No ripple, never filled.
 */
@Composable
fun SbInputChips(values: List<String>, onRemove: (Int) -> Unit, groupLabel: String, modifier: Modifier = Modifier) {
    SbFlowRow(
        modifier.semantics {
            contentDescription = groupLabel
            isTraversalGroup = true
        },
        horizontalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s2),
    ) {
        values.forEachIndexed { index, value -> SbInputChip(value) { onRemove(index) } }
    }
}

/** One input chip: the frame 6 dp in from top and bottom, the word 12 dp from the start, the 48 dp remove button. */
@Composable
private fun SbInputChip(value: String, onRemove: () -> Unit) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val name = sbMessages().removeValue(value)
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val inset = t.space.s3 / 2   // 6 dp: the 36 dp frame in a 48 dp row (spec/02 §2.9, the web's inset: 6px 0)
    Row(
        Modifier
            .heightIn(min = t.size.targetTouch)
            .drawBehind {
                val w = t.borderWidth.control.toPx()
                val y = inset.toPx()
                drawRoundRect(
                    c.borderStrong,
                    topLeft = Offset(w / 2f, y + w / 2f),
                    size = Size(size.width - w, size.height - 2 * y - w),
                    cornerRadius = CornerRadius(t.radius.control.toPx()),
                    style = Stroke(width = w),
                )
            }
            .padding(start = t.space.s3),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(
            value,
            style = ty.label.copy(fontWeight = ty.caption.fontWeight),
            color = c.text,
            maxLines = 1,
            modifier = Modifier.padding(vertical = inset),
        )
        Box(
            Modifier
                .size(t.size.targetTouch)
                .clickable(interactionSource = interaction, indication = null, role = Role.Button, onClick = onRemove)
                .semantics { contentDescription = name },
            contentAlignment = Alignment.Center,
        ) {
            Box(Modifier.matchParentSize().padding(inset).sbFocusRingInset(interaction))
            Icon(
                SebaroIcons.Outline16.Close,
                contentDescription = null,
                tint = if (pressed || hovered) c.text else c.textMuted,
                modifier = Modifier.size(t.size.iconSm),
            )
        }
    }
}
